import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DiAOIirN.js";var i=JSON.parse(`{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1787084291000}`),a={name:`guide/getting-started.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><ul><li><strong>Node.js 22 or newer</strong> (or Docker)</li><li>Internet access to the public OpenStreetMap services</li></ul><p>That is the whole list. There is no account to create, no token to obtain and no server of your own to run — the defaults point at the free public OpenStreetMap services.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to “Install”">​</a></h2><p>Nothing to install permanently — <code>npx</code> fetches the package on first run:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">claude</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> mcp</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> add</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> osm</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> --</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> npx</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> osm-mcp</span></span></code></pre></div><p>For every other client, see <a href="/guide/clients">Connecting clients</a>.</p><h2 id="first-call" tabindex="-1">First call <a class="header-anchor" href="#first-call" aria-label="Permalink to “First call”">​</a></h2><p>Ask your assistant something that needs the map:</p><blockquote><p>How far is it from the Eiffel Tower to the Louvre, on foot?</p></blockquote><p>It should call <code>route</code> with <code>profile: &quot;foot&quot;</code> and come back with a distance and a walking time. A good second question, because it exercises geocoding, Overpass and the matrix logic in one go:</p><blockquote><p>Find a cafe that&#39;s a fair meeting point between Gare du Nord and Bastille.</p></blockquote><p>That is <code>suggest_meeting_point</code>.</p><h2 id="check-it-by-hand" tabindex="-1">Check it by hand <a class="header-anchor" href="#check-it-by-hand" aria-label="Permalink to “Check it by hand”">​</a></h2><p>If you would rather see the protocol, the <a href="https://github.com/modelcontextprotocol/inspector" target="_blank" rel="noreferrer">MCP Inspector</a> lists the tools and lets you call them one at a time — again with no environment needed:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">npx</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> @modelcontextprotocol/inspector</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> npx</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> osm-mcp</span></span></code></pre></div><p><code>straight_line_distance</code> is the cheapest smoke test with a network: it geocodes its two places and then computes offline. <code>map_link</code> with coordinates (<code>place: &quot;48.858,2.294&quot;</code>) works with no upstream call at all.</p><h2 id="expect-it-to-be-deliberately-unhurried" tabindex="-1">Expect it to be deliberately unhurried <a class="header-anchor" href="#expect-it-to-be-deliberately-unhurried" aria-label="Permalink to “Expect it to be deliberately unhurried”">​</a></h2><p>The server throttles itself to about one request per second per service, because that is what the public Nominatim and FOSSGIS usage policies ask for. A tool call that needs several geocodes — a 12-stop <code>optimize_route</code>, say — takes several seconds by design. Identical requests are served from an in-memory cache (default: one hour), so repeated questions about the same places are fast.</p><h2 id="optional-an-openrouteservice-key" tabindex="-1">Optional: an OpenRouteService key <a class="header-anchor" href="#optional-an-openrouteservice-key" aria-label="Permalink to “Optional: an OpenRouteService key”">​</a></h2><p>Everything works without one. If you set <code>ORS_API_KEY</code>, routes, matrices and isochrones switch from the shared OSRM/Valhalla demo servers to <a href="https://openrouteservice.org" target="_blank" rel="noreferrer">OpenRouteService</a> and its per-key quota (free tier: 2 000 directions/day, 40/minute):</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">claude</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> mcp</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> add</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> osm</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -e</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> ORS_API_KEY=…</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> --</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> npx</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> osm-mcp</span></span></code></pre></div><p>See <a href="/guide/configuration">Configuration</a> for what changes and what does not (<code>optimize_route</code> always uses OSRM).</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/guide/configuration">Configuration</a> — every environment variable</li><li><a href="/guide/faq">FAQ &amp; troubleshooting</a> — walking routes, rate limits, self-hosting</li></ul>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};